#include <iostream>
#include <string>

int main() {
    std::string input_str;
    std::getline(std::cin, input_str);
    char part1 = input_str[0];
    std::string middle = input_str.substr(1, input_str.size() - 2);
    char part2 = input_str.back();

    size_t pos;
    while ((pos = middle.find("dot")) != std::string::npos) {
        middle.replace(pos, 3, ".");
    }
    size_t at_pos = middle.find("at");
    if (at_pos != std::string::npos) {
        middle.replace(at_pos, 2, "@");
    }

    std::cout << part1 << middle << part2 << std::endl;
    return 0;
}
